from itertools import product
from typing import Callable, List, Set, Tuple

World = int
Relation = Set[Tuple[World, World]]
Pred = Callable[[World], bool]

def box(worlds: List[World], R: Relation, A: Pred) -> Pred:
    return lambda w: all(A(v) for v in worlds if (w, v) in R)

def glob(worlds: List[World], T: Relation, A: Pred) -> Pred:
    return lambda w: all(A(v) for v in worlds if (w, v) in T)

def fut(worlds: List[World], T: Relation, A: Pred) -> Pred:
    return lambda w: any(A(v) for v in worlds if (w, v) in T)

def all_predicates(worlds: List[World]) -> List[Pred]:
    out: List[Pred] = []
    for bits in product([False, True], repeat=len(worlds)):
        table = dict(zip(worlds, bits))
        out.append(lambda w, t=table: t[w])
    return out

worlds = list(range(4))
R = {(i, j) for i in worlds for j in worlds if i < j}      # acyclic, transitive
T = {(i, j) for i in worlds for j in worlds if i <= j}     # reflexive order

def loeb_ok() -> bool:
    for A in all_predicates(worlds):
        bA = box(worlds, R, A)
        hyp = box(worlds, R, lambda v, bA=bA, A=A: (not bA(v)) or A(v))
        if not all((not hyp(w)) or bA(w) for w in worlds):
            return False
    return True

def temporal_ok() -> bool:
    for A in all_predicates(worlds):
        bA = box(worlds, R, A)
        bbf = box(worlds, R, box(worlds, R, fut(worlds, T, A)))
        if not all((not bA(w)) or bbf(w) for w in worlds):
            return False
    return True

print("Lob sound:", loeb_ok())
print("Temporal axiom sound:", temporal_ok())

