function BOX(worlds, R, A):
    return  λ w. for all v in worlds with R(w,v): A(v)

function GLOB(worlds, T, A):
    return  λ w. for all v in worlds with T(w,v): A(v)

function FUT(worlds, T, A):
    return  λ w. exists v in worlds with T(w,v) and A(v)

function EVAL(formula, worlds, R, T, valuation):
    match formula:
      Atom p        -> valuation[p]
      Not  f        -> λ w. not EVAL(f)(w)
      And  f g      -> λ w. EVAL(f)(w) and EVAL(g)(w)
      Box  f        -> BOX (worlds, R, EVAL(f))
      Glob f        -> GLOB(worlds, T, EVAL(f))
      Fut  f        -> FUT (worlds, T, EVAL(f))

