function IS_TRANSITIVE(W, R):
    for x,y,z in W^3: if R(x,y) and R(y,z) and not R(x,z): return False
    return True

function CONVERSE_WELL_FOUNDED(W, R):   # acyclicity via DFS 3-colouring
    colour[w] := WHITE for all w
    function DFS(u):
        colour[u] := GREY
        for v in W with R(u,v):
            if colour[v] = GREY: return False        # back edge => cycle
            if colour[v] = WHITE and not DFS(v): return False
        colour[u] := BLACK; return True
    for w in W: if colour[w] = WHITE and not DFS(w): return False
    return True

function COMPAT(W, R, T):
    for w,wp,v in W^3: if T(w,wp) and R(wp,v) and not R(w,v): return False
    return True

function VALIDATE(W, R, T):
    return IS_TRANSITIVE(W,R) and CONVERSE_WELL_FOUNDED(W,R)
       and REFLEXIVE(W,T) and IS_TRANSITIVE(W,T) and COMPAT(W,R,T)

